rows = [l.split('|') for l in (D.parent/'wind_works.txt').read_text(encoding='utf-8').splitlines() if l and not l.startswith('#')]
out = {}
for r in rows:
    k = r[0]
    assert k in A, ('about がない', k)
    y, s1, s2 = A[k]
    out[r[1] + '|' + r[2]] = dict(y=y, s=f'【どんな曲】{s1}\n\n【聴くときのコツ】{s2}')
assert set(A) == {r[0] for r in rows}, set(A) ^ {r[0] for r in rows}
(D/'w1.json').write_text(json.dumps(out, ensure_ascii=False, indent=1), encoding='utf-8')
print('about', len(out))
